            var heading=new Label{Text=title,Font=new Font(Font.FontFamily,10,FontStyle.Bold),Tag="heading",Dock=DockStyle.Fill,TextAlign=ContentAlignment.BottomLeft,AccessibleName="Configuration section: "+title,Padding=new Padding(2,6,0,2)};Row("",heading,36);int row=fields.RowCount-1;var caption=fields.GetControlFromPosition(0,row);fields.Controls.Remove(caption);caption.Dispose();fields.SetColumn(heading,0);fields.SetColumnSpan(heading,2);
        }
        private bool ExtraFields(ActionKind kind)
