            if(kind==ActionKind.Repeat){Section("Repeat this block");var until=Check("Repeat until stopped or Break",Value.Count==0,delegate(bool v){if(v){Value.Count=0;Value.CountMax=0;}});var count=new NumericUpDown{Minimum=1,Maximum=1000000,Value=Math.Max(1,Value.Count)};Row("Number of repeats",count,42);var max=new NumericUpDown{Minimum=0,Maximum=1000000,Value=Value.CountMax};Row("Random upper limit",max,42);Action update=delegate{count.Enabled=max.Enabled=!until.Checked;};until.CheckedChanged+=delegate{update();};update();apply.Add(delegate{Value.Count=until.Checked?0:(int)count.Value;Value.CountMax=until.Checked?0:(int)max.Value;});Row("",new Label{Text="Put actions between Repeat and End Repeat. Leave the upper limit at 0 for an exact count. Stop always ends playback.",Tag="muted"},68);return true;}
            if(kind==ActionKind.CopyFile){Section("Copy a file");TextField("Source file",Value.Target,delegate(string value){Value.Target=value;},false);TextField("Destination file",Value.Text,delegate(string value){Value.Text=value;},false);Row("",new Label{Text="Use full file paths, including the new filename. An existing destination is not overwritten.",Tag="muted"},58);return true;}
            if(kind==ActionKind.MoveWindow){Section("Window position and size");TextField("Window title contains",Value.Text,delegate(string value){Value.Text=value;},false);Number("Left",Value.X,-100000,100000,delegate(int value){Value.X=value;});Number("Top",Value.Y,-100000,100000,delegate(int value){Value.Y=value;});Number("Width (pixels)",Value.Width,0,32768,delegate(int value){Value.Width=value;});Number("Height (pixels)",Value.Height,0,32768,delegate(int value){Value.Height=value;});return true;}
            if(kind==ActionKind.ClipboardIncrement){Section("Update a clipboard number");Number("Amount to add",Value.DelayMs,0,86400000,delegate(int value){Value.DelayMs=value;});Row("",new Label{Text="Example: clipboard 41 + amount 1 → clipboard 42. The clipboard must contain an integer.",Tag="muted"},62);return true;}
            if(kind==ActionKind.FindPixel||kind==ActionKind.WaitPixel||kind==ActionKind.IfPixel){Section("Color and search region");TextField("RGB color",Value.ColorRgb,delegate(string value){Value.ColorRgb=value;},false);Number("Color tolerance",Value.Tolerance,0,255,delegate(int value){Value.Tolerance=value;});var region=Choices("Search area",new[]{"Entire desktop","Foreground window","Selected rectangle"},Math.Max(0,(int)Value.SearchIn-1),delegate(int value){Value.SearchIn=(SearchArea)(value+1);});int first=fields.RowCount;Number("Rectangle X",Value.X,-100000,100000,delegate(int v){Value.X=v;});Number("Rectangle Y",Value.Y,-100000,100000,delegate(int v){Value.Y=v;});Number("Width (pixels)",Value.Width,0,32768,delegate(int v){Value.Width=v;});Number("Height (pixels)",Value.Height,0,32768,delegate(int v){Value.Height=v;});int last=fields.RowCount;Action show=delegate{bool visible=((RadioButton)region.Controls[2]).Checked;for(int row=first;row<last;row++){fields.RowStyles[row].Height=visible?40:0;for(int c=0;c<2;c++)fields.GetControlFromPosition(c,row).Visible=visible;}};foreach(RadioButton radio in region.Controls)radio.CheckedChanged+=delegate{show();};show();Section("Match behavior");Check("Move pointer to successful match",Value.MoveToMatch,delegate(bool v){Value.MoveToMatch=v;});if(kind==ActionKind.IfPixel){Check("Invert: IF color is NOT found",Value.Negate,delegate(bool v){Value.Negate=v;});Check("Wait before deciding the IF branch",Value.WaitForMatch,delegate(bool v){Value.WaitForMatch=v;});}if(kind==ActionKind.WaitPixel||kind==ActionKind.IfPixel){TimeField("Timeout",Value.TimeoutMs,delegate(int n){Value.TimeoutMs=n;});TimeField("Check every",Value.PollMs,delegate(int n){Value.PollMs=n;},10,60000,false);}Row("",new Label{Text="RGB example: #42C6AE. Tolerance 0 requires the exact color. A rectangle needs positive width and height.",Tag="muted"},65);return true;}
            if(kind==ActionKind.Pause||kind==ActionKind.Break||kind==ActionKind.Else||kind==ActionKind.EndIf||kind==ActionKind.EndRepeat||kind==ActionKind.ClipboardClear||kind==ActionKind.Paste){Section("How this step behaves");Row("",new Label{Text=ActionCatalog.Describe(kind)+"\r\n\r\n"+ActionExamples.For(kind),Tag="muted"},170);return true;}
            return false;
        }
    }
